const o={ui:{fig:"Fig. 1",title:"Cesta de tela · anatomía",svgLabel:"Dibujo isométrico de la cesta de tela con forro y de cómo se cose, paso a paso.",prev:"Paso anterior",dot:(e,a)=>e?`Paso ${e}: ${a}`:a,start:"Pasos →",next:"Siguiente →",overview:"Vista general",stepOf:(e,a)=>`Paso ${e} de ${a}`,machine:e=>`Máquina: ${e.toLowerCase()}`,inThisStep:"En este paso",takeApart:"Desarmar",putTogether:"Armar",replay:"↻ Repetir",parts:"Piezas",allSteps:"Instrucciones paso a paso",endView:"CORTE",cutTitle:"Cesta de tela · medidas de corte",cutAlt:"Esquema de corte de una cesta de tela con forro: el exterior y el forro, cada uno un cuadrado de 60 × 60 cm con un cuadrado de 20 × 20 cm recortado en cada esquina, y cinco cuadrados de entretela de 19 × 19 cm.",cutCaption:"Las piezas que hay que cortar, con sus medidas, como en el paso 1."},stitches:{straight:"Puntada recta"},labels:{cm60:"60 cm",cm20:"20 cm",cm19:"19 cm",cutCorners:"recortar las esquinas",outerCotton:"exterior · algodón",liningCotton:"forro · algodón",iface5:"5 × entretela",wrongSideUp:"exterior, revés arriba",ironOn:"fijar con la plancha",edges05:"a 0,5 cm de los bordes",turnOver:"dar la vuelta",rightSideIn:"derecho hacia dentro",seam05:"costura 0,5 cm",toThePoint:"hasta la punta",opening15:"abertura de 15 cm",sameAsOuter:"igual que el exterior",outerRightOut:"exterior al derecho",rightSides:"derecho con derecho",turnThrough:"vuelta por la abertura",stitchClosed:"cerrar la abertura",pushLining:"meter el forro dentro",topstitch05:"pespunte a 0,5 cm",hotGlue:"pegar en caliente, sin coser",jointFlat:"unión en un lado plano",bows4:"un lazo en cada esquina",christmas:"Navidad: encaje + lazos",halloween:"Halloween: cinta negra",everyday:"a diario: sin adornos"},steps:[{title:"La cesta terminada",text:"Una cesta de tela con forro: exterior de algodón reforzado con entretela, forro de algodón, y encaje y lazos pegados. Toca la cesta para desarmarla."},{title:"Corta las piezas",text:"Exterior y forro: un cuadrado de algodón de 60 × 60 cm cada uno, con un cuadrado de 20 × 20 cm recortado en cada esquina. Entretela: cinco cuadrados de 19 × 19 cm.",details:["Corta un cuadrado de algodón de 60 × 60 cm para el exterior y otro igual para el forro.","De cada esquina de los dos cuadrados, recorta un cuadrado de 20 × 20 cm. Lo que queda es una cruz: el cuadrado del centro es la base y los cuatro brazos son las paredes.","De entretela termoadhesiva gruesa, corta cinco cuadrados de 19 × 19 cm: uno para la base y uno para cada pared del exterior.","Todos los márgenes de costura de esta cesta son de 0,5 cm.","En el video, el texto en pantalla dice 50 × 50 cm: es un error, los cuadrados son de 60 × 60 cm."]},{title:"Plancha la entretela",text:"Coloca el exterior con el revés hacia arriba. Pon un cuadrado de entretela en el centro de la base y de cada pared, a 0,5 cm de los bordes, y pégalo con la plancha.",details:["Coloca la cruz exterior con el revés hacia arriba.","Pon un cuadrado de entretela, con el lado adhesivo hacia abajo, en el centro de la base y de cada una de las cuatro paredes, a 0,5 cm de los bordes por todos los lados, para que no quede dentro de las costuras.","Pega los cuadrados con la plancha. La entretela va solo en el exterior, no en el forro."]},{title:"Cose el exterior",text:"Da la vuelta al exterior para que quede con el derecho hacia arriba y levanta las paredes. Sujeta con alfileres los bordes que se juntan y cose las cuatro costuras de las esquinas, a 0,5 cm, desde arriba hasta la punta.",details:["Da la vuelta a la cruz exterior, con el derecho hacia arriba.","Levanta las paredes para que los bordes de dos paredes vecinas se junten, derecho con derecho. Sujétalos con alfileres.","Cose la costura de la esquina a 0,5 cm del borde, desde el borde superior hasta la punta, en la base. Sin rematar.","Cose las cuatro esquinas. Ahora el exterior es una caja del revés: la entretela queda por fuera."]},{title:"Cose el forro",text:"Haz el forro de la misma manera, sin entretela, pero deja una abertura de 15 cm en una costura de esquina. Por ella le darás la vuelta a la cesta.",details:["Levanta las paredes de la cruz del forro, derecho con derecho, y sujeta con alfileres los bordes que se juntan.","Cose tres costuras de esquina a 0,5 cm del borde, desde arriba hasta la punta.","Cose también la cuarta, pero deja en ella una abertura de 15 cm. Es así de grande porque las paredes del exterior, con entretela, son rígidas y necesitan espacio para pasar.","Deja el forro del revés."]},{title:"Une el exterior y el forro",text:"Da la vuelta al exterior al derecho y mételo dentro del forro, que está del revés, derecho con derecho. Cose todo el contorno de arriba a 0,5 cm del borde.",details:["Da la vuelta al exterior al derecho.","Mételo dentro del forro, que sigue del revés, de modo que los derechos queden enfrentados. Alinea las costuras de las esquinas y los bordes superiores.","Cose todo el contorno de arriba a 0,5 cm del borde."]},{title:"Dale la vuelta",text:"Da la vuelta a la cesta al derecho por la abertura del forro y luego cierra la abertura a máquina.",details:["Saca toda la cesta al derecho por la abertura de 15 cm del forro.","Mete hacia dentro los bordes sin acabar de la abertura y ciérrala a máquina, al ras del borde."]},{title:"Pespuntea el borde superior",text:"Mete el forro dentro de la cesta y pespuntea todo el contorno de arriba a 0,5 cm del borde.",details:["Empuja el forro hacia dentro de la cesta, hasta el fondo de las esquinas.","Pespuntea todo el contorno de arriba a 0,5 cm del borde. La cesta está terminada; los adornos, como tú quieras."]},{title:"Añade los adornos",text:"Con pegamento caliente, pega una cinta alrededor del borde superior, con la unión en un lado plano, y un lazo en cada esquina. Sirve cualquier cinta y cualquier lazo, o ninguno.",details:["Los adornos se pegan con una pistola de pegamento caliente, no se cosen.","Pega una cinta alrededor de todo el borde superior. Pon la unión en la parte plana de una pared, no en una esquina.","Pega un lazo en cada una de las cuatro esquinas. En el video están hechos de antemano con cinta blanca y tienen una media perla roja de plástico pegada en el centro; los lazos ya hechos sirven igual de bien.","Sirve cualquier cinta, de cualquier ancho: encaje para Navidad, como en el video; una cinta negra lisa o una naranja con calabazas para Halloween; o ningún adorno, para todos los días. En el video, la cesta lleva mandarinas en la mesa de Navidad; usa la tuya para lo que quieras."]}],legend:[{title:"Exterior",text:"algodón · un cuadrado de 60 × 60 cm con un cuadrado de 20 × 20 cm recortado en cada esquina"},{title:"Entretela ×5",text:"gruesa, termoadhesiva · cuadrados de 19 × 19 cm en la base y las paredes del exterior, a 0,5 cm de los bordes"},{title:"Forro",text:"algodón · la misma cruz que el exterior, sin entretela"},{title:"Cinta",text:"encaje o cualquier cinta · pegada alrededor del borde superior con pegamento caliente, la unión en un lado plano"},{title:"Lazos ×4",text:"uno en cada esquina, pegados, con una media perla roja en el centro"},{title:"Costuras",text:"todas de 0,5 cm · una abertura de 15 cm en una costura de esquina del forro · pespunte a 0,5 cm del borde superior"}]};export{o as default};
